static void setup_clock ( struct kvm_vm * vm , struct test_case * test_case ) { struct kvm_clock_data data ; data . clock = test_case -> kvmclock_base ; if ( test_case -> realtime_offset ) { struct timespec ts ; int r ; data . flags |= KVM_CLOCK_REALTIME ; { r = clock_gettime ( CLOCK_REALTIME , & ts ) ; if ( ! r ) { break ; } } errno == EINTR ; TEST_ASSERT ( ! r , "clock_gettime() failed: %d\n" , r ) ; data . realtime = ts . tv_sec * NSEC_PER_SEC ; data . realtime += ts . tv_nsec ; data . realtime += test_case -> realtime_offset ; } vm_ioctl ( vm , KVM_SET_CLOCK , & data ) ; } 